import math
from collections import Counter


def _chi2_sf(x, df):
    if x <= 0:
        return 1.0
    y = x / 2.0
    logy = math.log(y)
    if df % 2 == 0:
        m = df // 2
        total = 0.0
        for i in range(m):
            total += math.exp(-y + i * logy - math.lgamma(i + 1))
    else:
        n = (df - 1) // 2
        total = math.erfc(math.sqrt(y))
        for k in range(1, n + 1):
            total += math.exp(-y + (k - 0.5) * logy - math.lgamma(k + 0.5))
    if total < 0.0:
        total = 0.0
    if total > 1.0:
        total = 1.0
    return total


def item_location_independence_test(records):
    if not records:
        return None
    items = sorted(set(r[0] for r in records))
    locs = sorted(set(r[1] for r in records))
    if len(items) < 2 or len(locs) < 2:
        return None
    counts = Counter((r[0], r[1]) for r in records)
    row_tot = Counter(r[0] for r in records)
    col_tot = Counter(r[1] for r in records)
    n = float(len(records))
    chi2 = 0.0
    for it in items:
        for lc in locs:
            e = row_tot[it] * col_tot[lc] / n
            o = counts.get((it, lc), 0)
            chi2 += (o - e) ** 2 / e
    dof = (len(items) - 1) * (len(locs) - 1)
    p = _chi2_sf(chi2, dof)
    return (float(chi2), float(p), int(dof))

