from collections import Counter

import numpy as np
from scipy.stats import chi2_contingency


def item_location_independence_test(records):
    if not records:
        return None
    items = sorted({r[0] for r in records})
    locations = sorted({r[1] for r in records})
    if len(items) < 2 or len(locations) < 2:
        return None
    item_idx = {it: i for i, it in enumerate(items)}
    loc_idx = {lo: j for j, lo in enumerate(locations)}
    table = np.zeros((len(items), len(locations)), dtype=float)
    for (it, lo), c in Counter((r[0], r[1]) for r in records).items():
        table[item_idx[it], loc_idx[lo]] += c
    chi2_stat, p_value, dof, _ = chi2_contingency(table, correction=False)
    return (float(chi2_stat), float(p_value), int(dof))

