import math


def _gamma_p_q(a, x):
    """Return the regularized lower and upper incomplete gamma functions (P, Q)."""
    if x <= 0:
        return 0.0, 1.0
    gln = math.lgamma(a)
    if x < a + 1.0:
        # Series expansion
        ap = a
        s = 1.0 / a
        d = s
        for _ in range(100000):
            ap += 1.0
            d *= x / ap
            s += d
            if abs(d) < abs(s) * 1e-16:
                break
        p = s * math.exp(-x + a * math.log(x) - gln)
        p = min(max(p, 0.0), 1.0)
        return p, 1.0 - p
    else:
        # Continued fraction (modified Lentz)
        tiny = 1e-300
        b = x + 1.0 - a
        c = 1.0 / tiny
        d = 1.0 / b
        h = d
        for i in range(1, 100000):
            an = -i * (i - a)
            b += 2.0
            d = an * d + b
            if abs(d) < tiny:
                d = tiny
            c = b + an / c
            if abs(c) < tiny:
                c = tiny
            d = 1.0 / d
            de = d * c
            h *= de
            if abs(de - 1.0) < 1e-16:
                break
        q = math.exp(-x + a * math.log(x) - gln) * h
        q = min(max(q, 0.0), 1.0)
        return 1.0 - q, q


def _chi2_cdf(x, df):
    return _gamma_p_q(df / 2.0, x / 2.0)[0]


def _chi2_sf(x, df):
    return _gamma_p_q(df / 2.0, x / 2.0)[1]


def _chi2_ppf(p, df):
    if p <= 0:
        return 0.0
    lo = 0.0
    hi = max(1.0, float(df))
    while _chi2_cdf(hi, df) < p:
        lo = hi
        hi *= 2.0
    for _ in range(300):
        mid = (lo + hi) / 2.0
        if _chi2_cdf(mid, df) < p:
            lo = mid
        else:
            hi = mid
        if hi - lo <= 1e-14 * max(1.0, hi):
            break
    return (lo + hi) / 2.0


def pet_shop_sales_report(daily_customers, sales, confidence):
    if daily_customers is None or len(daily_customers) == 0:
        raise ValueError("daily_customers must not be empty")
    try:
        conf = float(confidence)
    except (TypeError, ValueError):
        raise ValueError("confidence must be a number")
    if not (0.0 < conf < 1.0):
        raise ValueError("confidence must be strictly between 0 and 1")
    if sales is None or len(sales) < 2:
        raise ValueError("sales must have at least two animal types")
    counts = list(sales.values())
    total_sales = sum(counts)
    if total_sales <= 0:
        raise ValueError("total number of sales must be positive")

    n = len(daily_customers)
    total = sum(daily_customers)
    mean = float(total) / n

    alpha = 1.0 - conf
    if total == 0:
        low = 0.0
    else:
        low = _chi2_ppf(alpha / 2.0, 2 * total) / 2.0 / n
    high = _chi2_ppf(1.0 - alpha / 2.0, 2 * total + 2) / 2.0 / n

    k = len(counts)
    expected = total_sales / float(k)
    chi2 = sum((c - expected) ** 2 / expected for c in counts)
    p_value = _chi2_sf(chi2, k - 1)

    return {
        'mean': mean,
        'ci': (round(low, 4), round(high, 4)),
        'chi2': float(chi2),
        'p_value': round(p_value, 4),
    }

import re
from html.parser import HTMLParser

VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr', 'keygen', 'command'}
P_CLOSERS = {'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl', 'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol', 'p', 'pre', 'section', 'table', 'ul', 'dir', 'center', 'summary', 'listing', 'xmp'}
SCOPE = {'html', 'table', 'td', 'th', 'caption', 'button', 'marquee', 'object', 'applet', 'template'}


class _El:
    __slots__ = ('tag', 'attrs', 'children', 'parent')

    def __init__(self, tag, attrs, parent):
        self.tag = tag
        self.attrs = attrs
        self.children = []
        self.parent = parent


class _Builder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _El('#root', {}, None)
        self.stack = [self.root]

    def _close_nearest(self, names, stops):
        for i in range(len(self.stack) - 1, 0, -1):
            t = self.stack[i].tag
            if t in names:
                del self.stack[i:]
                return
            if t in stops:
                return

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in P_CLOSERS:
            self._close_nearest({'p'}, SCOPE)
        if tag == 'li':
            self._close_nearest({'li'}, {'ul', 'ol'} | SCOPE)
        elif tag in ('dt', 'dd'):
            self._close_nearest({'dt', 'dd'}, {'dl'} | SCOPE)
        elif tag in ('option', 'optgroup'):
            if self.stack[-1].tag == 'option':
                self.stack.pop()
        elif tag == 'tr':
            self._close_nearest({'tr'}, {'table', 'tbody', 'thead', 'tfoot'})
        elif tag in ('td', 'th'):
            self._close_nearest({'td', 'th'}, {'tr', 'table'})
        elif tag in ('tbody', 'thead', 'tfoot'):
            self._close_nearest({'tbody', 'thead', 'tfoot'}, {'table'})
        d = {}
        for k, v in attrs:
            k = k.lower()
            if k not in d:
                d[k] = '' if v is None else v
        parent = self.stack[-1]
        el = _El(tag, d, parent)
        parent.children.append(el)
        if tag not in VOID:
            self.stack.append(el)

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        self.handle_starttag(tag, attrs)
        if tag not in VOID and self.stack[-1].tag == tag:
            self.stack.pop()

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in VOID:
            return
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


_PART = re.compile(r'''\*|\.([\w-]+)|#([\w-]+)|\[\s*([^\s=\]]+)\s*(?:=\s*(?:"([^"]*)"|'([^']*)'|([^\]\s]*)))?\s*\]|([\w-]+)''')


def _parse_compound(s):
    tests = []
    for m in _PART.finditer(s):
        g = m.group(0)
        if g == '*':
            continue
        if m.group(1) is not None:
            tests.append(('class', m.group(1)))
        elif m.group(2) is not None:
            tests.append(('id', m.group(2)))
        elif m.group(3) is not None:
            name = m.group(3).lower()
            val = None
            for gi in (4, 5, 6):
                if m.group(gi) is not None:
                    val = m.group(gi)
                    break
            tests.append(('attr', (name, val)))
        elif m.group(7) is not None:
            tests.append(('tag', m.group(7).lower()))
    return tests


def _parse_selector(sel):
    compounds, combs = [], []
    cur = ''
    pending = None
    quote = None
    bracket = False
    for ch in sel:
        if quote:
            cur += ch
            if ch == quote:
                quote = None
        elif bracket:
            cur += ch
            if ch in '"\'':
                quote = ch
            elif ch == ']':
                bracket = False
        elif ch.isspace() or ch == '>':
            if cur:
                compounds.append(cur)
                cur = ''
            if ch == '>':
                pending = '>'
            elif pending is None:
                pending = ' '
        else:
            if not cur and compounds:
                combs.append(pending or ' ')
            if not cur:
                pending = None
            if ch == '[':
                bracket = True
            cur += ch
    if cur:
        compounds.append(cur)
    return [_parse_compound(c) for c in compounds], combs


def _match_compound(el, tests):
    for kind, v in tests:
        if kind == 'tag':
            if el.tag != v:
                return False
        elif kind == 'class':
            if v not in el.attrs.get('class', '').split():
                return False
        elif kind == 'id':
            if el.attrs.get('id') != v:
                return False
        else:
            name, val = v
            if name not in el.attrs:
                return False
            if val is not None and el.attrs[name] != val:
                return False
    return True


def _matches(el, comps, combs, i):
    if el is None or el.tag == '#root':
        return False
    if not _match_compound(el, comps[i]):
        return False
    if i == 0:
        return True
    if combs[i - 1] == '>':
        return _matches(el.parent, comps, combs, i - 1)
    anc = el.parent
    while anc is not None and anc.tag != '#root':
        if _matches(anc, comps, combs, i - 1):
            return True
        anc = anc.parent
    return False


def _text(el):
    out = []
    st = [el]
    while st:
        n = st.pop()
        if isinstance(n, str):
            out.append(n)
        else:
            st.extend(reversed(n.children))
    return ''.join(out)


def texts_matching_selector(html, selector):
    b = _Builder()
    b.feed(html)
    b.close()
    comps, combs = _parse_selector(selector)
    if not comps:
        return []
    last = len(comps) - 1
    result = []
    st = list(reversed([c for c in b.root.children if not isinstance(c, str)]))
    while st:
        el = st.pop()
        if _matches(el, comps, combs, last):
            result.append(_text(el).strip())
        st.extend(reversed([c for c in el.children if not isinstance(c, str)]))
    return result

import math


def _gammainc_upper_reg(a, x):
    if x <= 0:
        return 1.0
    gln = math.lgamma(a)
    if x < a + 1.0:
        ap = a
        s = 1.0 / a
        d = s
        for _ in range(100000):
            ap += 1.0
            d *= x / ap
            s += d
            if abs(d) < abs(s) * 1e-16:
                break
        p = s * math.exp(-x + a * math.log(x) - gln)
        return max(0.0, min(1.0, 1.0 - p))
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 100000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        de = d * c
        h *= de
        if abs(de - 1.0) < 1e-16:
            break
    q = math.exp(-x + a * math.log(x) - gln) * h
    return max(0.0, min(1.0, q))


def _chi2_sf(x, df):
    if x <= 0:
        return 1.0
    return _gammainc_upper_reg(df / 2.0, x / 2.0)


def residual_ljung_box(values, period, lags):
    if not isinstance(period, int) or period < 2:
        raise ValueError("period must be at least 2")
    vals = [float(v) for v in values]
    n = len(vals)
    if n < 2 * period:
        raise ValueError("need at least 2 * period values")
    if period % 2 == 0:
        w = [1.0 / period] * (period + 1)
        w[0] = w[-1] = 0.5 / period
    else:
        w = [1.0 / period] * period
    half = len(w) // 2
    trend = [None] * n
    for i in range(half, n - half):
        s = 0.0
        for j, wj in enumerate(w):
            s += wj * vals[i - half + j]
        trend[i] = s
    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        if trend[i] is not None:
            sums[i % period] += vals[i] - trend[i]
            counts[i % period] += 1
    phase = [sums[k] / counts[k] if counts[k] else 0.0 for k in range(period)]
    mp = sum(phase) / period
    seasonal = [p - mp for p in phase]
    resid = [vals[i] - trend[i] - seasonal[i % period] for i in range(n) if trend[i] is not None]
    m = len(resid)
    if not isinstance(lags, int) or lags < 1 or lags >= m:
        raise ValueError("invalid lags")
    mean = sum(resid) / m
    dm = [r - mean for r in resid]
    c0 = sum(d * d for d in dm)
    if c0 == 0:
        return (0.0, 1.0)
    q = 0.0
    for k in range(1, lags + 1):
        ck = sum(dm[t] * dm[t + k] for t in range(m - k))
        r = ck / c0
        q += r * r / (m - k)
    q *= m * (m + 2)
    p = _chi2_sf(q, lags)
    return (float(q), float(p))

