import math


def _chi2_sf(x, k):
    try:
        from scipy.stats import chi2
        return float(chi2.sf(x, k))
    except Exception:
        pass
    a = k / 2.0
    xx = x / 2.0
    if xx <= 0:
        return 1.0
    gln = math.lgamma(a)
    if xx < a + 1:
        ap = a
        s = 1.0 / a
        d = s
        for _ in range(10000):
            ap += 1
            d *= xx / ap
            s += d
            if abs(d) < abs(s) * 1e-15:
                break
        p = s * math.exp(-xx + a * math.log(xx) - gln)
        return max(0.0, 1.0 - p)
    tiny = 1e-300
    b = xx + 1 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    for i in range(1, 10000):
        an = -i * (i - a)
        b += 2
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        de = d * c
        h *= de
        if abs(de - 1) < 1e-15:
            break
    return math.exp(-xx + a * math.log(xx) - gln) * h


def residual_ljung_box(values, period, lags):
    if not isinstance(period, int) or period < 2:
        raise ValueError("period must be an integer >= 2")
    x = [float(v) for v in values]
    n = len(x)
    if n < 2 * period:
        raise ValueError("need at least 2 * period values")
    half = period // 2
    if period % 2 == 0:
        w = [0.5 / period] + [1.0 / period] * (period - 1) + [0.5 / period]
    else:
        w = [1.0 / period] * period
    trend = [None] * n
    for i in range(half, n - half):
        s = 0.0
        for j, wj in enumerate(w):
            s += wj * x[i - half + j]
        trend[i] = s
    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        if trend[i] is not None:
            sums[i % period] += x[i] - trend[i]
            counts[i % period] += 1
    avgs = [sums[p] / counts[p] for p in range(period)]
    m = sum(avgs) / period
    seas = [a - m for a in avgs]
    resid = [x[i] - trend[i] - seas[i % period] for i in range(n) if trend[i] is not None]
    nr = len(resid)
    if not isinstance(lags, int) or lags < 1 or lags >= nr:
        raise ValueError("invalid lags")
    mean = sum(resid) / nr
    d = [r - mean for r in resid]
    denom = sum(v * v for v in d)
    if denom == 0:
        return (float('nan'), float('nan'))
    q = 0.0
    for k in range(1, lags + 1):
        rk = sum(d[t] * d[t + k] for t in range(nr - k)) / denom
        q += rk * rk / (nr - k)
    q *= nr * (nr + 2)
    p = _chi2_sf(q, lags)
    return (float(q), float(p))

