import math


def _betacf(a, b, x, maxiter=20000, eps=1e-16):
    tiny = 1e-300
    qab = a + b
    qap = a + 1.0
    qam = a - 1.0
    c = 1.0
    d = 1.0 - qab * x / qap
    if abs(d) < tiny:
        d = tiny
    d = 1.0 / d
    h = d
    for m in range(1, maxiter + 1):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        if abs(d) < tiny:
            d = tiny
        c = 1.0 + aa / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        if abs(d) < tiny:
            d = tiny
        c = 1.0 + aa / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        de = d * c
        h *= de
        if abs(de - 1.0) < eps:
            break
    return h


def _betainc(a, b, x, y):
    # regularized incomplete beta I_x(a,b), with y = 1 - x supplied precisely
    if x <= 0.0:
        return 0.0
    if y <= 0.0:
        return 1.0
    lbt = (math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
           + a * math.log(x) + b * math.log(y))
    if x < (a + 1.0) / (a + b + 2.0):
        return math.exp(lbt) * _betacf(a, b, x) / a
    return 1.0 - math.exp(lbt) * _betacf(b, a, y) / b


def _t_tail(t, df):
    # P(T > t) for t >= 0
    if t <= 0.0:
        return 0.5
    t2 = t * t
    denom = df + t2
    x = df / denom
    y = t2 / denom
    return 0.5 * _betainc(df / 2.0, 0.5, x, y)


def _t_tail_inv(q, df):
    # find t >= 0 with P(T > t) = q, 0 < q < 0.5
    lo = 0.0
    hi = 1.0
    while _t_tail(hi, df) > q:
        lo = hi
        hi *= 2.0
        if hi > 1e150:
            break
    for _ in range(2000):
        mid = 0.5 * (lo + hi)
        if mid <= lo or mid >= hi:
            break
        if _t_tail(mid, df) > q:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def _t_ppf(p, df):
    if p == 0.5:
        return 0.0
    if p > 0.5:
        return _t_tail_inv(1.0 - p, df)
    return -_t_tail_inv(p, df)


def t_qq_plot_data(values, df):
    try:
        dfv = float(df)
    except (TypeError, ValueError):
        raise ValueError("df must be a positive number")
    if not (dfv > 0) or math.isnan(dfv):
        raise ValueError("df must be positive")
    ordered = sorted(float(v) for v in values)
    n = len(ordered)
    if n < 3:
        raise ValueError("need at least 3 values")
    if ordered[0] == ordered[-1]:
        raise ValueError("all values are identical")
    mn = 0.5 ** (1.0 / n)
    positions = []
    for i in range(1, n + 1):
        if i == 1:
            positions.append(1.0 - mn)
        elif i == n:
            positions.append(mn)
        else:
            positions.append((i - 0.3175) / (n + 0.365))
    theoretical = [_t_ppf(p, dfv) for p in positions]
    xbar = sum(theoretical) / n
    ybar = sum(ordered) / n
    sxx = sum((x - xbar) ** 2 for x in theoretical)
    syy = sum((y - ybar) ** 2 for y in ordered)
    sxy = sum((x - xbar) * (y - ybar) for x, y in zip(theoretical, ordered))
    slope = sxy / sxx
    intercept = ybar - slope * xbar
    r = sxy / math.sqrt(sxx * syy)
    return (theoretical, ordered, slope, intercept, r)

import math


def cluster_quality_scores(points, labels):
    n = len(points)
    if len(labels) != n:
        raise ValueError("labels and points must have the same length")
    clusters = {}
    for i, lab in enumerate(labels):
        clusters.setdefault(lab, []).append(i)
    k = len(clusters)
    if k < 2 or k >= n:
        raise ValueError("number of distinct labels must be in [2, n_points - 1]")
    pts = [[float(v) for v in p] for p in points]
    dim = len(pts[0]) if pts else 0
    keys = list(clusters.keys())
    label_idx = {lab: j for j, lab in enumerate(keys)}
    lab_of = [label_idx[l] for l in labels]
    members = [clusters[key] for key in keys]

    # Silhouette
    total_s = 0.0
    for i in range(n):
        ci = lab_of[i]
        if len(members[ci]) == 1:
            continue
        sums = [0.0] * k
        for j in range(n):
            if j != i:
