import struct

try:
    import blake3 as _blake3_mod
    _HAVE_PKG = hasattr(_blake3_mod, 'blake3')
except Exception:
    _HAVE_PKG = False

_M = 0xFFFFFFFF
_IV = [0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
       0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19]
_PERM = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8]
_CHUNK_START = 1
_CHUNK_END = 2
_PARENT = 4
_ROOT = 8
_KEYED_HASH = 16
_CHUNK_LEN = 1024
_BLOCK_LEN = 64


def _g(s, a, b, c, d, mx, my):
    s[a] = (s[a] + s[b] + mx) & _M
    x = s[d] ^ s[a]; s[d] = ((x >> 16) | (x << 16)) & _M
    s[c] = (s[c] + s[d]) & _M
    x = s[b] ^ s[c]; s[b] = ((x >> 12) | (x << 20)) & _M
    s[a] = (s[a] + s[b] + my) & _M
    x = s[d] ^ s[a]; s[d] = ((x >> 8) | (x << 24)) & _M
    s[c] = (s[c] + s[d]) & _M
    x = s[b] ^ s[c]; s[b] = ((x >> 7) | (x << 25)) & _M


def _round(s, m):
    _g(s, 0, 4, 8, 12, m[0], m[1])
    _g(s, 1, 5, 9, 13, m[2], m[3])
    _g(s, 2, 6, 10, 14, m[4], m[5])
    _g(s, 3, 7, 11, 15, m[6], m[7])
    _g(s, 0, 5, 10, 15, m[8], m[9])
    _g(s, 1, 6, 11, 12, m[10], m[11])
    _g(s, 2, 7, 8, 13, m[12], m[13])
    _g(s, 3, 4, 9, 14, m[14], m[15])


def _compress(cv, m, counter, block_len, flags):
    s = list(cv[:8]) + _IV[:4] + [counter & _M, (counter >> 32) & _M, block_len, flags]
    m = list(m)
    for r in range(7):
        _round(s, m)
        if r < 6:
            m = [m[i] for i in _PERM]
    for i in range(8):
        s[i] ^= s[i + 8]
        s[i + 8] ^= cv[i]
    return s


def _words(block):
    block = bytes(block) + b'\x00' * (64 - len(block))
    return list(struct.unpack('<16I', block))


class _Output:
    def __init__(self, cv, m, counter, block_len, flags):
        self.cv, self.m, self.counter, self.block_len, self.flags = cv, m, counter, block_len, flags

    def chaining_value(self):
        return _compress(self.cv, self.m, self.counter, self.block_len, self.flags)[:8]

    def root_bytes(self, n):
        out = bytearray()
        c = 0
        while len(out) < n:
            w = _compress(self.cv, self.m, c, self.block_len, self.flags | _ROOT)
            out += struct.pack('<16I', *w)
            c += 1
        return bytes(out[:n])


class _ChunkState:
    def __init__(self, key_words, counter, flags):
        self.cv = list(key_words)
        self.counter = counter
        self.block = bytearray()
        self.blocks_compressed = 0
        self.flags = flags

    def length(self):
        return _BLOCK_LEN * self.blocks_compressed + len(self.block)

    def _start(self):
        return _CHUNK_START if self.blocks_compressed == 0 else 0

    def update(self, data, pos, end):
        while pos < end:
            if len(self.block) == _BLOCK_LEN:
                self.cv = _compress(self.cv, _words(self.block), self.counter, _BLOCK_LEN,
                                    self.flags | self._start())[:8]
                self.blocks_compressed += 1
                self.block = bytearray()
            take = min(_BLOCK_LEN - len(self.block), end - pos)
            self.block += data[pos:pos + take]
            pos += take

    def output(self):
        return _Output(self.cv, _words(self.block), self.counter, len(self.block),
                       self.flags | self._start() | _CHUNK_END)


def _parent_output(l, r, key_words, flags):
    return _Output(key_words, list(l) + list(r), 0, _BLOCK_LEN, flags | _PARENT)


class _Hasher:
    def __init__(self, key=None):
        if key is None:
            self.key_words = list(_IV)
            self.flags = 0
        else:
            self.key_words = list(struct.unpack('<8I', key))
            self.flags = _KEYED_HASH
        self.stack = []
        self.chunk = _ChunkState(self.key_words, 0, self.flags)

    def _add_cv(self, cv, total):
        while total & 1 == 0:
            cv = _parent_output(self.stack.pop(), cv, self.key_words, self.flags).chaining_value()
            total >>= 1
        self.stack.append(cv)

    def update(self, data):
        data = memoryview(data)
        pos, n = 0, len(data)
        while pos < n:
            if self.chunk.length() == _CHUNK_LEN:
                cv = self.chunk.output().chaining_value()
                total = self.chunk.counter + 1
                self._add_cv(cv, total)
                self.chunk = _ChunkState(self.key_words, total, self.flags)
            take = min(_CHUNK_LEN - self.chunk.length(), n - pos)
            self.chunk.update(data, pos, pos + take)
            pos += take

    def finalize(self, n):
        out = self.chunk.output()
        for cv in reversed(self.stack):
            out = _parent_output(cv, out.chaining_value(), self.key_words, self.flags)
        return out.root_bytes(n)


def _feed(h, message, repeat):
    if repeat == 0 or len(message) == 0:
        return
    per = max(1, (1 << 20) // len(message))
    if per >= repeat:
        h.update(message * repeat)
        return
    buf = message * per
    full, rem = divmod(repeat, per)
    for _ in range(full):
        h.update(buf)
    if rem:
        h.update(message * rem)


def blake3_hash_hex(message, repeat, key, length):
    if not isinstance(length, int) or length < 1:
        raise ValueError('length must be >= 1')
    if key is not None:
        key = bytes(key)
        if len(key) != 32:
            raise ValueError('key must be exactly 32 bytes')
    if repeat < 0:
        raise ValueError('repeat must be non-negative')
    message = bytes(message)
    if _HAVE_PKG:
        try:
            h = _blake3_mod.blake3(key=key) if key is not None else _blake3_mod.blake3()
            _feed(h, message, repeat)
            return h.digest(length=length).hex()
        except (TypeError, AttributeError):
            pass
    h = _Hasher(key)
    _feed(h, message, repeat)
    return h.finalize(length).hex()

