import math
from collections import Counter


def _gamma_series_p(a, x):
    # Regularized lower incomplete gamma P(a, x) by series expansion
    ap = a
    total = 1.0 / a
    delta = total
    for _ in range(100000):
        ap += 1.0
        delta *= x / ap
        total += delta
        if abs(delta) < abs(total) * 1e-16:
            break
    return total * math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gamma_cf_q(a, x):
    # Regularized upper incomplete gamma Q(a, x) by continued fraction (Lentz)
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    i = 1
    while i < 100000:
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < 1e-16:
            break
        i += 1
    return math.exp(-x + a * math.log(x) - math.lgamma(a)) * h


def _chi2_sf(chi2, df):
    if chi2 <= 0:
        return 1.0
    a = df / 2.0
    x = chi2 / 2.0
    if df == 2:
        return math.exp(-x)
    if df == 1:
        return math.erfc(math.sqrt(x))
    if x < a + 1.0:
        q = 1.0 - _gamma_series_p(a, x)
    else:
        q = _gamma_cf_q(a, x)
    return min(1.0, max(0.0, q))


def word_frequency_chi_square(words_a, words_b):
    if not words_a or not words_b:
        return None
    ca = Counter(str(w).strip().casefold() for w in words_a)
    cb = Counter(str(w).strip().casefold() for w in words_b)
    vocab = []
    seen = set()
    for w in list(ca.keys()) + list(cb.keys()):
        if w not in seen:
            seen.add(w)
            vocab.append(w)
    if len(vocab) < 2:
        return None
    rows = [[ca.get(w, 0) for w in vocab], [cb.get(w, 0) for w in vocab]]
    row_totals = [sum(r) for r in rows]
    col_totals = [rows[0][j] + rows[1][j] for j in range(len(vocab))]
    n = float(sum(row_totals))
    chi2 = 0.0
    for i in range(2):
        for j in range(len(vocab)):
            expected = row_totals[i] * col_totals[j] / n
            if expected > 0:
                diff = rows[i][j] - expected
                chi2 += diff * diff / expected
    df = len(vocab) - 1
    p = _chi2_sf(chi2, df)
    return (float(chi2), float(p), int(df))

