import numpy as np
from scipy.stats import chi2_contingency


def _normalize(word):
    if not isinstance(word, str):
        word = str(word)
    return word.strip().casefold()


def word_frequency_chi_square(words_a, words_b):
    if words_a is None or words_b is None:
        return None
    words_a = list(words_a)
    words_b = list(words_b)
    if len(words_a) == 0 or len(words_b) == 0:
        return None

    counts_a = Counter(_normalize(w) for w in words_a)
    counts_b = Counter(_normalize(w) for w in words_b)

    vocab = sorted(set(counts_a) | set(counts_b))
    if len(vocab) < 2:
        return None

    table = np.array(
        [
            [counts_a.get(w, 0) for w in vocab],
            [counts_b.get(w, 0) for w in vocab],
        ],
        dtype=float,
    )

