    return int.from_bytes(hashlib.sha512(data).digest(), 'little')


def ed25519_signature(seed_hex, message):
    if not isinstance(seed_hex, str):
        raise ValueError('seed_hex must be a hexadecimal string')
    if len(seed_hex) != 64 or any(c not in string.hexdigits for c in seed_hex):
        raise ValueError('seed_hex must be 64 hexadecimal characters (32 bytes)')
    try:
        seed = bytes.fromhex(seed_hex)
    except ValueError:
        raise ValueError('seed_hex is not valid hexadecimal')
    if len(seed) != 32:
        raise ValueError('seed must be exactly 32 bytes')
    message = bytes(message)

    h = hashlib.sha512(seed).digest()
    a = int.from_bytes(h[:32], 'little')
    a &= (1 << 254) - 8
    a |= 1 << 254
    prefix = h[32:]
    A = _compress(_point_mul(a, _G))

    r = _sha512_int(prefix + message) % _Q
    R = _compress(_point_mul(r, _G))
    k = _sha512_int(R + A + message) % _Q
    s = (r + k * a) % _Q
    return (R + int.to_bytes(s, 32, 'little')).hex()

import base64
import math


def _der_len(n):
    if n < 0x80:
        return bytes([n])
    b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
    return bytes([0x80 | len(b)]) + b


def _der_int(x):
    x = int(x)
    if x == 0:
        body = b'\x00'
    elif x > 0:
        body = x.to_bytes(x.bit_length() // 8 + 1, 'big')
        # strip redundant leading zeros while keeping sign bit clear
        while len(body) > 1 and body[0] == 0 and body[1] < 0x80:
            body = body[1:]
    else:
        length = (x.bit_length() + 8) // 8
        body = x.to_bytes(length, 'big', signed=True)
        while len(body) > 1 and body[0] == 0xFF and body[1] >= 0x80:
            body = body[1:]
    return b'\x02' + _der_len(len(body)) + body


def _der_seq(items):
    content = b''.join(_der_int(i) for i in items)
    return b'\x30' + _der_len(len(content)) + content


def _pem(label, der):
    b64 = base64.b64encode(der).decode('ascii')
    lines = [b64[i:i + 64] for i in range(0, len(b64), 64)]
    return '-----BEGIN %s-----\n' % label + ''.join(l + '\n' for l in lines) + '-----END %s-----\n' % label


def rsa_key_pems(p, q, e):
    p = int(p)
    q = int(q)
    e = int(e)
    if p == q:
        raise ValueError('p and q must be distinct')
    phi = (p - 1) * (q - 1)
    if phi == 0 or math.gcd(e, phi) != 1:
        raise ValueError('e is not coprime to (p-1)(q-1)')
    n = p * q
    d = pow(e, -1, phi)
    dp = d % (p - 1)
    dq = d % (q - 1)
    qinv = pow(q, -1, p)
    priv = _der_seq([0, n, e, d, p, q, dp, dq, qinv])
    pub = _der_seq([n, e])
    return (_pem('RSA PRIVATE KEY', priv), _pem('RSA PUBLIC KEY', pub))

