        for i in range(n):
            for j in range(i + 1, n):
                off += a[i][j] * a[i][j]
        diag = sum(a[i][i] * a[i][i] for i in range(n))
        if off <= 1e-30 * (diag + 1e-300) or off == 0.0:
            break
