            raise ValueError("n_components must be an integer")
    max_k = min(n - 1, p)
    if n_components < 1 or n_components > max_k:
        raise ValueError("n_components out of range")
    try:
        X = np.asarray(rows, dtype=float)
    except (TypeError, ValueError):
        raise ValueError("data must be numeric")
    if not np.all(np.isfinite(X)):
        raise ValueError("data must be finite")
    Xc = X - X.mean(axis=0)
    total = float(np.sum(Xc * Xc))
    scale = max(1.0, float(np.sum(X * X)))
    if not total > 1e-24 * scale:
        raise ValueError("data has zero total variance")
    U, S, Vt = np.linalg.svd(Xc, full_matrices=False)
    order = np.argsort(-S, kind="stable")
    S = S[order]
    Vt = Vt[order]
    variances = S ** 2
    comps = []
    for i in range(n_components):
        v = Vt[i].copy()
        idx = int(np.argmax(np.abs(v)))
