def pca_project(rows, n_components):
    try:
        data = [list(r) for r in rows]
    except TypeError:
        raise ValueError("rows must be a list of sequences")
    if len(data) < 2:
        raise ValueError("need at least 2 rows")
    ncols = len(data[0])
    if ncols == 0:
        raise ValueError("rows must be non-empty")
    for r in data:
        if len(r) != ncols:
            raise ValueError("rows must have equal length")
    if isinstance(n_components, bool) or not isinstance(n_components, (int, np.integer)):
        raise ValueError("n_components must be an integer")
    if n_components < 1 or n_components > ncols:
        raise ValueError("n_components out of range")
    try:
        X = np.array(data, dtype=float)
    except (TypeError, ValueError):
        raise ValueError("rows must contain numbers")
    if not np.all(np.isfinite(X)):
        raise ValueError("rows must contain finite numbers")
    if all(np.array_equal(X[0], X[i]) for i in range(1, X.shape[0])):
        raise ValueError("all rows are identical")
    Xc = X - X.mean(axis=0)
    cov = Xc.T @ Xc / (X.shape[0] - 1)
    cov = (cov + cov.T) / 2.0
    total = float(np.trace(cov))
    if total <= 0:
        raise ValueError("all rows are identical")
    vals, vecs = np.linalg.eigh(cov)
    order = sorted(range(len(vals)), key=lambda i: -vals[i])
    comps = []
    ratios = []
    for idx in order[:n_components]:
        v = vecs[:, idx].astype(float)
        v = v / np.linalg.norm(v)
        a = np.abs(v)
        m = a.max()
        tol = 1e-12 * max(1.0, m)
        first = int(np.nonzero(a >= m - tol)[0][0])
        if v[first] < 0:
            v = -v
        comps.append(v)
        ratios.append(max(float(vals[idx]), 0.0) / total)
    W = np.column_stack(comps)
    S = Xc @ W

    def r(x):
        y = round(float(x), 7)
        return y + 0.0 if y != 0 else 0.0

    scores = [[r(x) for x in row] for row in S]
    evr = [r(x) for x in ratios]
    return {'scores': scores, 'explained_variance_ratio': evr}

