            if not math.isfinite(v):
                raise ValueError("non-finite feature")
    for v in y:
        if not math.isfinite(v):
            raise ValueError("non-finite target")
    if n <= k + 1:
        raise ValueError("not enough observations")
    p = k + 1
    cols = [[1.0] * n] + [[rows[i][j] for i in range(n)] for j in range(k)]
    # Modified Gram-Schmidt with reorthogonalization
    Q = []
    R = [[0.0] * p for _ in range(p)]
    for j in range(p):
        c = cols[j]
        cnorm = math.sqrt(sum(v * v for v in c))
        if cnorm == 0.0:
            raise ValueError("rank-deficient design matrix")
        v = c[:]
        for _ in range(2):
            for i in range(j):
                qi = Q[i]
                rij = sum(qi[t] * v[t] for t in range(n))
                R[i][j] += rij
