        raise ValueError("constant target")
    ymean = sum(y) / n
    sst = sum((v - ymean) ** 2 for v in y)
    if sst <= 0.0:
        raise ValueError("constant target")
    z = [sum(Q[i][t] * y[t] for t in range(n)) for i in range(p)]
    beta = [0.0] * p
    for i in range(p - 1, -1, -1):
        s = z[i] - sum(R[i][j] * beta[j] for j in range(i + 1, p))
        beta[i] = s / R[i][i]
    # Inverse of R
    Rinv = [[0.0] * p for _ in range(p)]
    for col in range(p):
        for i in range(p - 1, -1, -1):
            rhs = 1.0 if i == col else 0.0
            s = rhs - sum(R[i][j] * Rinv[j][col] for j in range(i + 1, p))
