    ssr = max(sst - rss, 0.0)
    fstat = (ssr / k) / (rss / df)
    fp = _f_pvalue(fstat, k, df)
    return {
        'coefficients': coefs,
        'r_squared': _r(r2),
        'f_statistic': _r(fstat),
        'f_pvalue': _r(fp),
    }

