import math


def _jacobi_eig(A):
    n = len(A)
    a = [row[:] for row in A]
    V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for _ in range(100):
        off = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                off += a[i][j] * a[i][j]
        if off < 1e-30:
            break
        for p in range(n):
            for q in range(p + 1, n):
                if abs(a[p][q]) < 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * a[p][q])
                t = (1.0 if theta >= 0 else -1.0) / (abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = V[k][p]
                    vkq = V[k][q]
                    V[k][p] = c * vkp - s * vkq
                    V[k][q] = s * vkp + c * vkq
    return [a[i][i] for i in range(n)], V


def _pinv_solve(A, b):
    n = len(A)
    vals, V = _jacobi_eig(A)
    mx = max([abs(v) for v in vals] + [0.0])
    tol = mx * n * 1e-12
    x = [0.0] * n
    for i in range(n):
        if abs(vals[i]) > tol and vals[i] != 0.0:
            coef = sum(V[k][i] * b[k] for k in range(n)) / vals[i]
            for k in range(n):
                x[k] += coef * V[k][i]
    return x


def _solve(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]
    scale = max([abs(A[i][i]) for i in range(n)] + [0.0])
    tol = (scale if scale > 0 else 1.0) * 1e-12
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) <= tol:
            return _pinv_solve(A, b)
        M[col], M[piv] = M[piv], M[col]
        for r in range(col + 1, n):
            f = M[r][col] / M[col][col]
            if f != 0.0:
                for c in range(col, n + 1):
                    M[r][c] -= f * M[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n] - sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def _fit(X, y, alpha):
    n = len(X)
    p = len(X[0])
    xm = [sum(r[j] for r in X) / n for j in range(p)]
    ym = sum(y) / n
    Xc = [[r[j] - xm[j] for j in range(p)] for r in X]
    yc = [v - ym for v in y]
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p
    for r, t in zip(Xc, yc):
        for i in range(p):
            ri = r[i]
            b[i] += ri * t
            for j in range(i, p):
                A[i][j] += ri * r[j]
    for i in range(p):
        for j in range(i):
            A[i][j] = A[j][i]
        A[i][i] += alpha
    w = _solve(A, b)
    intercept = ym - sum(xm[j] * w[j] for j in range(p))
    return w, intercept


def _r2(y_true, y_pred):
    m = sum(y_true) / len(y_true)
    ss_tot = sum((v - m) ** 2 for v in y_true)
    ss_res = sum((a - b) ** 2 for a, b in zip(y_true, y_pred))
    if ss_tot == 0:
        return 1.0 if ss_res == 0 else 0.0
    return 1.0 - ss_res / ss_tot


def ridge_kfold_r2(features, targets, alpha, n_folds):
    if features is None or targets is None:
        raise ValueError("inputs must not be None")
    features = list(features)
    targets = list(targets)
    n = len(features)
    if n == 0 or len(targets) == 0:
        raise ValueError("inputs must not be empty")
    if n != len(targets):
        raise ValueError("rows and targets differ in number")
    X = []
    p = None
    for row in features:
        try:
            r = [float(v) for v in row]
        except TypeError:
            raise ValueError("each row must be a sequence of numbers")
        if p is None:
            p = len(r)
        if len(r) != p:
            raise ValueError("ragged rows")
        X.append(r)
    if not p:
        raise ValueError("rows have no features")
    y = [float(v) for v in targets]
    try:
        alpha = float(alpha)
    except (TypeError, ValueError):
        raise ValueError("alpha must be a number")
    if math.isnan(alpha) or alpha < 0:
        raise ValueError("alpha must be non-negative")
    if isinstance(n_folds, bool) or not isinstance(n_folds, int):
        if isinstance(n_folds, float) and n_folds.is_integer():
            n_folds = int(n_folds)
        else:
            raise ValueError("n_folds must be an integer")
    if n_folds < 2 or 2 * n_folds > n:
        raise ValueError("invalid n_folds")
    base, extra = divmod(n, n_folds)
    scores = []
    start = 0
    for k in range(n_folds):
        size = base + (1 if k < extra else 0)
        end = start + size
        Xtr = X[:start] + X[end:]
        ytr = y[:start] + y[end:]
        w, b0 = _fit(Xtr, ytr, alpha)
        preds = [b0 + sum(wj * xj for wj, xj in zip(w, r)) for r in X[start:end]]
        scores.append(_r2(y[start:end], preds))
        start = end
    return (sum(scores) / len(scores), scores)

