def corpus_bleu_score(references, hypotheses):
    if len(references) != len(hypotheses) or len(hypotheses) == 0:
        raise ValueError("references and hypotheses must be non-empty and of equal length")

    max_n = 4
    numerators = [0] * max_n
    denominators = [0] * max_n
    hyp_len_total = 0
    ref_len_total = 0

    for refs, hyp in zip(references, hypotheses):
        if isinstance(refs, str):
            refs = [refs]
        if not refs:
            raise ValueError("each hypothesis needs at least one reference")
        hyp_toks = hyp.split()
        ref_toks_list = [r.split() for r in refs]
        hyp_len = len(hyp_toks)
        hyp_len_total += hyp_len
        ref_lens = [len(r) for r in ref_toks_list]
        closest = min(ref_lens, key=lambda rl: (abs(rl - hyp_len), rl))
        ref_len_total += closest

        for n in range(1, max_n + 1):
            hyp_counts = _ngrams(hyp_toks, n)
            max_ref_counts = Counter()
            for rt in ref_toks_list:
                rc = _ngrams(rt, n)
                for g, c in rc.items():
                    if c > max_ref_counts[g]:
                        max_ref_counts[g] = c
            clipped = sum(min(c, max_ref_counts.get(g, 0)) for g, c in hyp_counts.items())
            total = sum(hyp_counts.values())
            numerators[n - 1] += clipped
            denominators[n - 1] += max(1, total)

