from scipy import stats


def anova_across_subjects(subjects, rows):
    n_sub = len(subjects)
    groups = []
    for j in range(n_sub):
        g = []
        for row in rows:
            if row is None or len(row) <= j + 1:
                continue
            v = row[j + 1]
            if v is None:
                continue
            g.append(float(v))
        if g:
            groups.append(g)
    k = len(groups)
    if k < 2:
        return None
    n = sum(len(g) for g in groups)
    if n <= k:
        return None
    if all(all(x == g[0] for x in g) for g in groups):
        return None
    grand = sum(sum(g) for g in groups) / n
    ssb = 0.0
    ssw = 0.0
    for g in groups:
        m = sum(g) / len(g)
        ssb += len(g) * (m - grand) ** 2
        ssw += sum((x - m) ** 2 for x in g)
    if ssw <= 0:
        return None
    dfb = k - 1
    dfw = n - k
    f = (ssb / dfb) / (ssw / dfw)
    p = float(stats.f.sf(f, dfb, dfw))
    return (float(f), p)

