_DESCR_RE = re.compile(r'^([<>|=]?)([?biuf])(\d*)$')


def _parse_descr(descr):
    if not isinstance(descr, str):
        raise ValueError('unsupported dtype')
    m = _DESCR_RE.match(descr)
    if not m:
        raise ValueError('unsupported dtype: %r' % (descr,))
    order, kind, size = m.groups()
    if kind == '?':
        if size not in ('', '1'):
            raise ValueError('unsupported dtype')
        kind, size = 'b', 1
    else:
        if size == '':
            raise ValueError('unsupported dtype')
        size = int(size)
    if kind == 'b':
        if size != 1:
            raise ValueError('unsupported dtype')
        code = 'B'
    elif kind == 'i':
        code = {1: 'b', 2: 'h', 4: 'i', 8: 'q'}.get(size)
    elif kind == 'u':
        code = {1: 'B', 2: 'H', 4: 'I', 8: 'Q'}.get(size)
    else:
        code = {2: 'e', 4: 'f', 8: 'd'}.get(size)
    if code is None:
        raise ValueError('unsupported dtype: %r' % (descr,))
    if order == '>':
        prefix = '>'
    elif order == '<':
        prefix = '<'
    else:
        prefix = '<' if sys.byteorder == 'little' else '>'
    return kind, size, prefix + code


def decode_npy_array(blob):
