        blob = bytes(blob)
    except Exception:
        raise ValueError('invalid input')
    if len(blob) < 8 or blob[:6] != b'\x93NUMPY':
        raise ValueError('not an npy file')
    major, minor = blob[6], blob[7]
    if minor != 0 or major not in (1, 2, 3):
        raise ValueError('unsupported npy version')
    if major == 1:
        if len(blob) < 10:
            raise ValueError('truncated header')
        hlen = struct.unpack('<H', blob[8:10])[0]
        start = 10
    else:
        if len(blob) < 12:
            raise ValueError('truncated header')
        hlen = struct.unpack('<I', blob[8:12])[0]
        start = 12
    end = start + hlen
    if end > len(blob):
        raise ValueError('truncated header')
    raw = blob[start:end]
    try:
        text = raw.decode('utf-8' if major == 3 else 'latin1')
    except Exception:
        raise ValueError('bad header encoding')
    try:
        header = ast.literal_eval(text.strip())
    except Exception:
        raise ValueError('malformed header')
    if not isinstance(header, dict):
        raise ValueError('malformed header')
    if set(header.keys()) != {'descr', 'fortran_order', 'shape'}:
        raise ValueError('malformed header keys')
    descr = header['descr']
    fortran = header['fortran_order']
    shape = header['shape']
    if not isinstance(fortran, bool):
        raise ValueError('malformed fortran_order')
    if not isinstance(shape, tuple):
        raise ValueError('malformed shape')
    for d in shape:
        if type(d) is not int or d < 0:
            raise ValueError('malformed shape')
    kind, size, fmt = _parse_descr(descr)
    count = 1
    for d in shape:
        count *= d
    nbytes = count * size
    if end + nbytes > len(blob):
        raise ValueError('truncated data')
    if count:
        fmt_full = fmt[0] + str(count) + fmt[1:]
        try:
            flat = list(struct.unpack(fmt_full, blob[end:end + nbytes]))
        except struct.error:
            raise ValueError('bad data')
    else:
        flat = []
    if kind == 'b':
        flat = [bool(v) for v in flat]
    elif kind == 'f':
        flat = [float(v) for v in flat]
    else:
        flat = [int(v) for v in flat]
    ndim = len(shape)
    if ndim == 0:
        return flat[0]
    strides = [0] * ndim
    if fortran:
        s = 1
        for k in range(ndim):
            strides[k] = s
            s *= shape[k]
    else:
        s = 1
        for k in range(ndim - 1, -1, -1):
            strides[k] = s
            s *= shape[k]

    def build(dim, off):
        n = shape[dim]
        st = strides[dim]
        if dim == ndim - 1:
            return [flat[off + i * st] for i in range(n)]
        return [build(dim + 1, off + i * st) for i in range(n)]

    if count == 0:
        def build_empty(dim):
            n = shape[dim]
            if n == 0 or dim == ndim - 1:
                return []
            return [build_empty(dim + 1) for _ in range(n)]
        return build_empty(0)
    return build(0, 0)

