import math


def _chi2_sf(x, dof):
    if x <= 0:
        return 1.0
    h = x / 2.0
    logh = math.log(h)
    if dof % 2 == 0:
        k = dof // 2
        total = 0.0
        for i in range(k):
            total += math.exp(-h + i * logh - math.lgamma(i + 1))
    else:
        n = (dof - 1) // 2
        total = math.erfc(math.sqrt(h))
        for i in range(1, n + 1):
            total += math.exp(-h + (i - 0.5) * logh - math.lgamma(i + 0.5))
    if total < 0.0:
        total = 0.0
    if total > 1.0:
        total = 1.0
    return float(total)


def chi_square_independence(xs, ys):
    xs = list(xs)
    ys = list(ys)
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    if len(xs) == 0:
        raise ValueError("inputs must not be empty")
    xcats = {}
    ycats = {}
    for v in xs:
        if v not in xcats:
            xcats[v] = len(xcats)
    for v in ys:
        if v not in ycats:
            ycats[v] = len(ycats)
    r = len(xcats)
    c = len(ycats)
    if r < 2 or c < 2:
        raise ValueError("each variable needs at least two distinct categories")
    table = [[0] * c for _ in range(r)]
    for a, b in zip(xs, ys):
        table[xcats[a]][ycats[b]] += 1
    n = len(xs)
    row_tot = [sum(row) for row in table]
    col_tot = [sum(table[i][j] for i in range(r)) for j in range(c)]
    stat = 0.0
    for i in range(r):
        for j in range(c):
            e = row_tot[i] * col_tot[j] / n
            d = table[i][j] - e
            stat += d * d / e
    dof = (r - 1) * (c - 1)
    p = _chi2_sf(stat, dof)
    return (float(stat), float(p), int(dof))

import math


def _invert(mat):
    n = len(mat)
    a = [list(row) + [1.0 if i == j else 0.0 for j in range(n)] for i, row in enumerate(mat)]
    scale = max((abs(v) for row in mat for v in row), default=0.0)
    tol = 1e-12 * (scale if scale > 0 else 1.0)
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(a[r][col]))
        if abs(a[piv][col]) <= tol:
            raise ValueError("singular design matrix")
        a[col], a[piv] = a[piv], a[col]
        p = a[col][col]
        a[col] = [v / p for v in a[col]]
        for r in range(n):
            if r != col:
                f = a[r][col]
                if f != 0.0:
                    rowc = a[col]
                    a[r] = [v - f * w for v, w in zip(a[r], rowc)]
    return [row[n:] for row in a]


def adf_test_statistic(series, lag):
    if isinstance(lag, bool) or not isinstance(lag, int):
        if isinstance(lag, float) and lag.is_integer():
            lag = int(lag)
        else:
            raise ValueError("lag must be an integer")
    if lag < 0:
        raise ValueError("lag must be non-negative")
    y = [float(v) for v in series]
    n = len(y)
    if n < 2 * lag + 4:
        raise ValueError("series too short")
    if all(v == y[0] for v in y):
        raise ValueError("series is constant")
    dy = [y[i + 1] - y[i] for i in range(n - 1)]
    nobs = n - 1 - lag
    # rows t = lag .. n-2 in dy index
    yresp = []
    cols = [[] for _ in range(lag + 1)]
    for t in range(lag, n - 1):
        yresp.append(dy[t])
        cols[0].append(y[t])
        for i in range(1, lag + 1):
            cols[i].append(dy[t - i])
    # demean (FWL for the constant)
    def demean(v):
        m = math.fsum(v) / len(v)
        return [x - m for x in v]
    yc = demean(yresp)
    xc = [demean(c) for c in cols]
    k = len(xc)
    xtx = [[math.fsum(a * b for a, b in zip(xc[i], xc[j])) for j in range(k)] for i in range(k)]
    xty = [math.fsum(a * b for a, b in zip(xc[i], yc)) for i in range(k)]
    inv = _invert(xtx)
    beta = [math.fsum(inv[i][j] * xty[j] for j in range(k)) for i in range(k)]
    resid = [yc[t] - math.fsum(beta[i] * xc[i][t] for i in range(k)) for t in range(nobs)]
    ssr = math.fsum(r * r for r in resid)
    df = nobs - (k + 1)
    if df <= 0:
        raise ValueError("not enough observations")
    s2 = ssr / df
    var_g = s2 * inv[0][0]
    gamma = beta[0]
    if var_g <= 0:
        if gamma == 0:
            stat = float('nan')
        else:
            stat = -math.inf if gamma < 0 else math.inf
    else:
        stat = gamma / math.sqrt(var_g)
    return (float(stat), int(nobs))

