import numpy as np


def adf_test_statistic(series, lag):
    if isinstance(lag, bool):
        raise ValueError("lag must be an integer")
    try:
        lag_int = int(lag)
    except (TypeError, ValueError):
        raise ValueError("lag must be an integer")
    if lag_int != lag:
        raise ValueError("lag must be an integer")
    lag = lag_int
    if lag < 0:
        raise ValueError("lag must be non-negative")
    y = np.asarray(list(series), dtype=float).ravel()
    n = y.shape[0]
    if n < 2 * lag + 4:
        raise ValueError("series too short for the requested lag")
    if not np.all(np.isfinite(y)):
        raise ValueError("series contains non-finite values")
    if np.all(y == y[0]):
        raise ValueError("series is constant")

    dy = np.diff(y)  # length n-1
    nobs = n - 1 - lag
    # dependent variable: dy_t for t = lag..n-2 (indices into dy)
    Y = dy[lag:]
    cols = [np.ones(nobs), y[lag:n - 1]]
    for i in range(1, lag + 1):
        cols.append(dy[lag - i:n - 1 - i])
    X = np.column_stack(cols)

    XtX = X.T @ X
    try:
        XtX_inv = np.linalg.inv(XtX)
    except np.linalg.LinAlgError:
        XtX_inv = np.linalg.pinv(XtX)
    beta = XtX_inv @ (X.T @ Y)
    resid = Y - X @ beta
    k = X.shape[1]
    df = nobs - k
    if df <= 0:
        raise ValueError("not enough observations")
    ssr = float(resid @ resid)
    s2 = ssr / df
    var_gamma = s2 * XtX_inv[1, 1]
    gamma = float(beta[1])
    with np.errstate(divide='ignore', invalid='ignore'):
        if var_gamma <= 0:
            if gamma == 0:
                stat = float('nan')
            else:
                stat = float('-inf') if gamma < 0 else float('inf')
        else:
            stat = gamma / np.sqrt(var_gamma)
    return float(stat), int(nobs)

