    if kind == 'MS':
        days = [1]
    elif kind == 'ME':
        days = [last]
    elif kind == 'BMS':
        d = 1
        while datetime.date(y, m, d).weekday() >= 5:
            d += 1
        days = [d]
    elif kind == 'BME':
        d = last
        while datetime.date(y, m, d).weekday() >= 5:
            d -= 1
        days = [d]
    elif kind == 'SMS':
        days = [1, 15]
    elif kind == 'SME':
        days = [15, last]
    elif kind == 'QS':
        days = [1] if m in (1, 4, 7, 10) else []
    elif kind == 'QE':
        days = [last] if m in (3, 6, 9, 12) else []
    elif kind == 'YS':
        days = [1] if m == 1 else []
    elif kind == 'YE':
        days = [31] if m == 12 else []
    elif kind == 'WOM':
        n, wd = arg
        w0 = datetime.date(y, m, 1).weekday()
        first = 1 + (wd - w0) % 7
        days = [first + 7 * (n - 1)]
    else:
        days = []
    return [datetime.date(y, m, d) for d in days]


def price_schedule(start_date, prices, freq):
    kind, arg = _parse_freq(freq)
    prices = list(prices)
