    out = []
    for line in lines:
        if line[:1] in (' ', '\t') and out:
            out[-1] += line[1:]
        else:
            out.append(line)
    return out


def _split_line(line):
    # returns (name_without_group_upper, value) or None
    in_q = False
    name_end = None
    for i, ch in enumerate(line):
        if ch == '"':
            in_q = not in_q
        elif not in_q:
            if ch == ';' and name_end is None:
                name_end = i
            elif ch == ':':
                if name_end is None:
                    name_end = i
                name = line[:name_end].strip()
                if '.' in name:
                    name = name.rsplit('.', 1)[1]
                return name.upper(), line[i + 1:]
    return None


def _decode(value):
    res = []
    i = 0
    n = len(value)
    while i < n:
        ch = value[i]
        if ch == '\\' and i + 1 < n:
            nx = value[i + 1]
            if nx in ('n', 'N'):
                res.append('\n')
            else:
                res.append(nx)
            i += 2
        else:
            res.append(ch)
            i += 1
    return ''.join(res)


def extract_vcard_contacts(vcf_text):
