import math
from bisect import bisect_right


def _gammaincc(a, x):
    if x <= 0:
        return 1.0
    if math.isinf(x):
        return 0.0
    eps = 1e-15
    fpmin = 1e-300
    lg = -x + a * math.log(x) - math.lgamma(a)
    if x < a + 1.0:
        ap = a
        s = 1.0 / a
        d = s
        for _ in range(100000):
            ap += 1.0
            d *= x / ap
            s += d
            if abs(d) < abs(s) * eps:
                break
        p = s * math.exp(lg)
        return max(0.0, min(1.0, 1.0 - p))
    b = x + 1.0 - a
    c = 1.0 / fpmin
    d = 1.0 / b
    h = d
    for i in range(1, 100000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < fpmin:
            d = fpmin
        c = b + an / c
        if abs(c) < fpmin:
            c = fpmin
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < eps:
            break
    return max(0.0, min(1.0, math.exp(lg) * h))


def _chi2_sf(x, df):
    if x != x:
        return float('nan')
    if x <= 0:
        return 1.0
    return _gammaincc(df / 2.0, x / 2.0)


def _norm_cdf(x, mu, sigma):
    return 0.5 * math.erfc(-(x - mu) / (sigma * math.sqrt(2.0)))


def histogram_normality_chisquare(values):
    data = [float(v) for v in values if v is not None]
    n = len(data)
    if n < 8:
        return None
    mn = min(data)
    mx = max(data)
    if mn == mx:
        return None
    k = min(11, n // 2)
    width = (mx - mn) / k
    edges = [mn + i * width for i in range(k + 1)]
    edges[-1] = mx
    counts = [0] * k
    for v in data:
        idx = bisect_right(edges, v) - 1
        if idx < 0:
            idx = 0
        if idx > k - 1:
            idx = k - 1
        counts[idx] += 1
    mean = sum(data) / n
    var = sum((v - mean) ** 2 for v in data) / (n - 1)
    sd = math.sqrt(var)
    if sd <= 0:
        return None
    cdfs = [0.0] + [_norm_cdf(edges[i], mean, sd) for i in range(1, k)] + [1.0]
    stat = 0.0
    for i in range(k):
        p = cdfs[i + 1] - cdfs[i]
        e = n * p
        o = counts[i]
        if e <= 0:
            if o > 0:
                stat = float('inf')
            continue
        stat += (o - e) ** 2 / e
    df = k - 3
    if math.isinf(stat):
        pval = 0.0
    else:
        pval = _chi2_sf(stat, df)
    return (float(stat), float(pval))

import math


def _jacobi_eigen(matrix):
    n = len(matrix)
    a = [row[:] for row in matrix]
    v = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    norm = sum(a[i][j] ** 2 for i in range(n) for j in range(n))
    for _ in range(200):
        off = sum(a[i][j] ** 2 for i in range(n) for j in range(i + 1, n))
        if off <= 1e-30 * norm or off == 0.0:
            break
        for p in range(n):
            for q in range(p + 1, n):
                apq = a[p][q]
                if abs(apq) < 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * apq)
                sgn = 1.0 if theta >= 0 else -1.0
                t = sgn / (abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = v[k][p]
                    vkq = v[k][q]
                    v[k][p] = c * vkp - s * vkq
                    v[k][q] = s * vkp + c * vkq
    vals = [a[i][i] for i in range(n)]
    vecs = [[v[k][i] for k in range(n)] for i in range(n)]
    return vals, vecs


