    return round(x, 6) + 0.0


def principal_component_scores(data, n_components):
    try:
        rows = [list(r) for r in data]
    except TypeError:
        raise ValueError("invalid data")
    if len(rows) < 2:
        raise ValueError("need at least 2 rows")
    p = len(rows[0])
    if p == 0:
        raise ValueError("empty rows")
    for r in rows:
        if len(r) != p:
            raise ValueError("rows of unequal length")
    if isinstance(n_components, bool) or not isinstance(n_components, int):
        raise ValueError("n_components must be an integer")
    if n_components < 1 or n_components > p:
        raise ValueError("n_components out of range")
    rows = [[float(x) for x in r] for r in rows]
    n = len(rows)
    if all(all(r[j] == rows[0][j] for r in rows) for j in range(p)):
        raise ValueError("all columns are constant")
    means = [math.fsum(r[j] for r in rows) / n for j in range(p)]
    centred = [[r[j] - means[j] for j in range(p)] for r in rows]
    cov = [[0.0] * p for _ in range(p)]
    for i in range(p):
        for j in range(i, p):
            val = math.fsum(r[i] * r[j] for r in centred) / (n - 1)
            cov[i][j] = val
            cov[j][i] = val
    total = math.fsum(cov[i][i] for i in range(p))
    if total <= 0:
        raise ValueError("all columns are constant")
    vals, vecs = _jacobi_eigen(cov)
    order = sorted(range(p), key=lambda i: -vals[i])[:n_components]
    comps = []
    ratios = []
    for idx in order:
        vec = vecs[idx]
        nrm = math.sqrt(sum(x * x for x in vec))
        vec = [x / nrm for x in vec]
        best = 0
        for k in range(p):
            if abs(vec[k]) > abs(vec[best]) + 1e-12:
                best = k
        if vec[best] < 0:
            vec = [-x for x in vec]
        comps.append(vec)
        ratios.append(_r(max(vals[idx], 0.0) / total))
    scores = []
    for r in centred:
        scores.append([_r(math.fsum(r[k] * c[k] for k in range(p))) for c in comps])
    return scores, ratios

