import numpy as np


def principal_component_scores(data, n_components):
    try:
        rows = [list(r) for r in data]
    except TypeError:
        raise ValueError("data must be a list of rows")
    if len(rows) < 2:
        raise ValueError("need at least 2 rows")
    p = len(rows[0])
    if p == 0 or any(len(r) != p for r in rows):
        raise ValueError("rows must be non-empty and of equal length")
    if isinstance(n_components, bool) or not isinstance(n_components, (int, np.integer)):
        raise ValueError("n_components must be an integer")
    if not (1 <= n_components <= p):
        raise ValueError("n_components out of range")
    try:
        X = np.array(rows, dtype=float)
    except (TypeError, ValueError):
        raise ValueError("data must be numeric")
    if not np.all(np.isfinite(X)):
        raise ValueError("data must be finite")
    Xc = X - X.mean(axis=0)
    n = X.shape[0]
    cov = Xc.T @ Xc / (n - 1)
    total = float(np.trace(cov))
    if total <= 0 or np.allclose(Xc, 0):
        raise ValueError("all columns are constant")
    vals, vecs = np.linalg.eigh(cov)
    order = sorted(range(p), key=lambda i: -vals[i])
    order = order[:n_components]
    comps = []
    variances = []
    for i in order:
        v = vecs[:, i].copy()
        norm = np.linalg.norm(v)
        if norm > 0:
            v = v / norm
        idx = int(np.argmax(np.abs(v)))
        if v[idx] < 0:
            v = -v
        comps.append(v)
        variances.append(max(float(vals[i]), 0.0))
    W = np.column_stack(comps)
    S = Xc @ W

    def r(x):
        y = round(float(x), 6)
        return 0.0 if y == 0 else y

    scores = [[r(x) for x in row] for row in S]
    ratios = [r(v / total) for v in variances]
    return (scores, ratios)

