import math


def _gammainc_lower_series(a, x):
    # regularized lower incomplete gamma P(a, x) via series
    term = 1.0 / a
    total = term
    n = a
    for _ in range(100000):
        n += 1.0
        term *= x / n
        total += term
        if abs(term) < abs(total) * 1e-17:
            break
    return total * math.exp(-x + a * math.log(x) - math.lgamma(a))


def _gammainc_upper_cf(a, x):
    # regularized upper incomplete gamma Q(a, x) via continued fraction (Lentz)
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b if b != 0 else 1.0 / tiny
    h = d
    for i in range(1, 100000):
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        delta = d * c
        h *= delta
        if abs(delta - 1.0) < 1e-16:
            break
    return math.exp(-x + a * math.log(x) - math.lgamma(a)) * h


def _chi2_sf(x, df):
    if x <= 0:
        return 1.0
    if df == 1:
        return math.erfc(math.sqrt(x / 2.0))
    if df == 2:
        return math.exp(-x / 2.0)
    a = df / 2.0
    z = x / 2.0
    if z < a + 1.0:
        q = 1.0 - _gammainc_lower_series(a, z)
    else:
        q = _gammainc_upper_cf(a, z)
    return min(1.0, max(0.0, q))


def color_state_independence_test(observations):
    pairs = []
    for obs in observations:
        if not isinstance(obs, str) or obs.count(':') != 1:
            raise ValueError("Each observation must contain exactly one colon: %r" % (obs,))
        color, state = obs.split(':')
        pairs.append((color, state))
    if not pairs:
        return None
    colors = []
    states = []
    cseen = set()
    sseen = set()
    for c, s in pairs:
        if c not in cseen:
            cseen.add(c)
            colors.append(c)
        if s not in sseen:
            sseen.add(s)
            states.append(s)
    if len(colors) < 2 or len(states) < 2:
        return None
    ci = {c: i for i, c in enumerate(colors)}
    si = {s: j for j, s in enumerate(states)}
    table = [[0] * len(states) for _ in colors]
    for c, s in pairs:
        table[ci[c]][si[s]] += 1
    n = float(len(pairs))
    row_tot = [sum(r) for r in table]
    col_tot = [sum(table[i][j] for i in range(len(colors))) for j in range(len(states))]
    chi2 = 0.0
    for i in range(len(colors)):
        for j in range(len(states)):
            e = row_tot[i] * col_tot[j] / n
            if e > 0:
                d = table[i][j] - e
                chi2 += d * d / e
    dof = (len(colors) - 1) * (len(states) - 1)
    p = _chi2_sf(chi2, dof)
    return (float(chi2), float(p), int(dof))

