import io
import re
import sqlite3

_INT_RE = re.compile(r'^[+-]?\d+$')
_NUM_RE = re.compile(r'^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$')
_INT_MIN = -(2 ** 63)
_INT_MAX = 2 ** 63 - 1


def _quote_ident(name):
    return '"' + name.replace('"', '""') + '"'


def _column_type(values):
    present = [v for v in values if v != '']
    has_missing = len(present) != len(values)
    if not values:
        return 'TEXT'
    if not present:
        return 'REAL'
    if all(_NUM_RE.match(v) for v in present):
        if not has_missing and all(_INT_RE.match(v) for v in present):
            if all(_INT_MIN <= int(v) <= _INT_MAX for v in present):
                return 'INTEGER'
        return 'REAL'
    return 'TEXT'


def query_csv_with_sql(csv_text, query):
    reader = csv.reader(io.StringIO(csv_text, newline=''))
    rows = [r for r in reader if r != []]
    conn = sqlite3.connect(':memory:')
    try:
        if rows:
            header = rows[0]
            data = rows[1:]
            ncols = len(header)
            types = []
            for i in range(ncols):
                col = [r[i] if i < len(r) else '' for r in data]
                types.append(_column_type(col))
            col_defs = ', '.join(_quote_ident(h) + ' ' + t for h, t in zip(header, types))
            conn.execute('CREATE TABLE data (' + col_defs + ')')
            converted = []
            for r in data:
                out = []
                for i in range(ncols):
                    v = r[i] if i < len(r) else ''
                    if v == '':
                        out.append(None)
                    elif types[i] == 'INTEGER':
                        out.append(int(v))
                    elif types[i] == 'REAL':
                        out.append(float(v))
                    else:
                        out.append(v)
                converted.append(out)
            if ncols:
                placeholders = ', '.join('?' for _ in range(ncols))
                conn.executemany('INSERT INTO data VALUES (' + placeholders + ')', converted)
            conn.commit()
        try:
            cur = conn.execute(query)
            if cur.description is None:
                return {'columns': [], 'rows': []}
            columns = [d[0] for d in cur.description]
            result_rows = [list(row) for row in cur.fetchall()]
        except Exception as e:
            raise ValueError(str(e)) from e
        return {'columns': columns, 'rows': result_rows}
    finally:
        conn.close()

