from decimal import Decimal

_pattern_cache = {}


def _translate_pattern(p):
    out = []
    i = 0
    n = len(p)
    in_class = False
    while i < n:
        c = p[i]
        if c == '\\' and i + 1 < n:
            nx = p[i + 1]
            if nx == 'd':
                out.append('0-9' if in_class else '[0-9]')
            elif nx == 'D' and not in_class:
                out.append('[^0-9]')
            elif nx == 'w':
                out.append('a-zA-Z0-9_' if in_class else '[a-zA-Z0-9_]')
            elif nx == 'W' and not in_class:
                out.append('[^a-zA-Z0-9_]')
            else:
                out.append(c + nx)
            i += 2
            continue
        if in_class:
            if c == ']':
                in_class = False
            out.append(c)
        else:
            if c == '[':
                in_class = True
                out.append(c)
                if i + 1 < n and p[i + 1] == '^':
                    out.append('^')
                    i += 1
            elif c == '$':
                out.append('\\Z')
            elif c == '(' and p.startswith('(?<', i) and i + 3 < n and p[i + 3] not in '=!':
                out.append('(?P<')
                i += 3
                continue
            else:
                out.append(c)
        i += 1
    return ''.join(out)


def _compile(p):
    if p in _pattern_cache:
        return _pattern_cache[p]
    try:
        r = re.compile(_translate_pattern(p))
    except re.error:
        r = re.compile(p)
    _pattern_cache[p] = r
    return r


def _is_number(x):
    return isinstance(x, (int, float, Decimal)) and not isinstance(x, bool)


def _is_integer(x):
    if isinstance(x, bool):
