    if isinstance(x, int):
        return True
    if isinstance(x, float):
        return x == x and x not in (float('inf'), float('-inf')) and x.is_integer()
    if isinstance(x, Decimal):
        return x.is_finite() and x == x.to_integral_value()
    return False


def _type_ok(x, t):
    if t == 'null':
        return x is None
    if t == 'boolean':
        return isinstance(x, bool)
    if t == 'string':
        return isinstance(x, str)
    if t == 'number':
        return _is_number(x)
    if t == 'integer':
        return _is_integer(x)
    if t == 'array':
        return isinstance(x, list)
    if t == 'object':
        return isinstance(x, dict)
