        if 'maximum' in schema and inst > schema['maximum']:
            fail = True
        if 'exclusiveMinimum' in schema and _is_number(schema['exclusiveMinimum']) and inst <= schema['exclusiveMinimum']:
            fail = True
        if 'exclusiveMaximum' in schema and _is_number(schema['exclusiveMaximum']) and inst >= schema['exclusiveMaximum']:
            fail = True
