    raise ValueError('Invalid JSON constant: ' + name)


def find_schema_violations(document_text, schema):
    if isinstance(document_text, (bytes, bytearray)):
        try:
            document_text = document_text.decode('utf-8')
        except UnicodeDecodeError as e:
            raise ValueError(str(e))
