import math


def _gammainc(a, x):
    """Return (P, Q) regularized lower/upper incomplete gamma."""
    if x <= 0:
        return 0.0, 1.0
    lnpre = -x + a * math.log(x) - math.lgamma(a)
    if x < a + 1.0:
        ap = a
        term = 1.0 / a
        s = term
        for _ in range(100000):
            ap += 1.0
            term *= x / ap
            s += term
            if abs(term) < abs(s) * 1e-17:
                break
        p = s * math.exp(lnpre)
        if p > 1.0:
            p = 1.0
        return p, 1.0 - p
    tiny = 1e-300
    b = x + 1.0 - a
    c = 1.0 / tiny
    d = 1.0 / b
    h = d
    i = 0
    while True:
        i += 1
        an = -i * (i - a)
        b += 2.0
        d = an * d + b
        if abs(d) < tiny:
            d = tiny
        c = b + an / c
        if abs(c) < tiny:
            c = tiny
        d = 1.0 / d
        de = d * c
        h *= de
        if abs(de - 1.0) < 1e-17 or i > 100000:
            break
    q = math.exp(lnpre) * h
    if q > 1.0:
        q = 1.0
    return 1.0 - q, q


def _gamma_ppf(a, p):
    """Solve P(a, x) = p for x (P regularized lower incomplete gamma)."""
    def below(x):
        P, Q = _gammainc(a, x)
        if p <= 0.5:
            return P < p
        return Q > 1.0 - p
    lo = 0.0
    hi = a + 1.0
    while below(hi):
        lo = hi
        hi *= 2.0
    for _ in range(2000):
        mid = (lo + hi) / 2.0
        if mid <= lo or mid >= hi:
            break
        if below(mid):
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2.0


def pet_shop_sales_report(daily_customers, sales, confidence):
    if daily_customers is None or len(daily_customers) == 0:
        raise ValueError("daily_customers must not be empty")
    try:
        conf = float(confidence)
    except (TypeError, ValueError):
        raise ValueError("confidence must be a number")
    if not (0.0 < conf < 1.0):
        raise ValueError("confidence must be strictly between 0 and 1")
    if sales is None or len(sales) < 2:
        raise ValueError("sales must have at least two animal types")
    counts = list(sales.values())
    total_sales = sum(counts)
    if total_sales <= 0:
        raise ValueError("total number of sales must be positive")

    n_days = len(daily_customers)
    total = sum(daily_customers)
    mean = float(total) / n_days
    alpha = 1.0 - conf
    if total == 0:
        low = 0.0
    else:
        low = _gamma_ppf(float(total), alpha / 2.0)
    high = _gamma_ppf(float(total) + 1.0, 1.0 - alpha / 2.0)
    ci = (float(low) / n_days, float(high) / n_days)

    k = len(counts)
    expected = float(total_sales) / k
    chi2 = float(sum((o - expected) ** 2 / expected for o in counts))
    df = k - 1
    if chi2 <= 0:
        p_value = 1.0
    else:
        p_value = _gammainc(df / 2.0, chi2 / 2.0)[1]
    return {'mean': mean, 'ci': ci, 'chi2': chi2, 'p_value': float(p_value)}

import math


def _jacobi_eigen(a):
    n = len(a)
    a = [row[:] for row in a]
    v = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    frob2 = sum(a[i][j] ** 2 for i in range(n) for j in range(n))
    if frob2 == 0:
        return [0.0] * n, v
    for _ in range(200):
        off = sum(a[i][j] ** 2 for i in range(n) for j in range(i + 1, n))
        if off == 0 or off < 1e-32 * frob2:
            break
        for p in range(n):
            for q in range(p + 1, n):
                apq = a[p][q]
                if apq == 0:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * apq)
                if abs(theta) > 1e150:
                    t = 1.0 / (2.0 * theta)
                else:
                    t = (1.0 if theta >= 0 else -1.0) / (abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = v[k][p]
                    vkq = v[k][q]
                    v[k][p] = c * vkp - s * vkq
                    v[k][q] = s * vkp + c * vkq
    vals = [a[i][i] for i in range(n)]
    return vals, v


def principal_component_scores(data, n_components):
    if data is None or len(data) == 0:
        raise ValueError("data must be non-empty")
    rows = [list(r) for r in data]
    m = len(rows[0])
    for r in rows:
        if len(r) != m:
            raise ValueError("rows have different lengths")
    n = len(rows)
    if isinstance(n_components, bool) or not isinstance(n_components, int):
        raise ValueError("n_components must be an integer")
    if n_components < 1 or n_components > min(n - 1, m):
        raise ValueError("n_components out of range")
    rows = [[float(x) for x in r] for r in rows]
    means = [math.fsum(r[j] for r in rows) / n for j in range(m)]
    centered = [[r[j] - means[j] for j in range(m)] for r in rows]
    cov = [[0.0] * m for _ in range(m)]
    for i in range(m):
        for j in range(i, m):
            val = math.fsum(c[i] * c[j] for c in centered) / (n - 1)
            cov[i][j] = val
            cov[j][i] = val
    total = math.fsum(cov[i][i] for i in range(m))
    scale = max(abs(x) for r in rows for x in r) if m > 0 else 0.0
    if total <= 0 or not (total > (1e-13 * scale) ** 2):
        raise ValueError("data has zero total variance")
    vals, vecs = _jacobi_eigen(cov)
    order = sorted(range(m), key=lambda i: -vals[i])
    comps = []
    ratios = []
    for idx in order[:n_components]:
        vec = [vecs[k][idx] for k in range(m)]
        norm = math.sqrt(math.fsum(x * x for x in vec))
        if norm > 0:
            vec = [x / norm for x in vec]
        best = 0
        for k in range(m):
            if abs(vec[k]) > abs(vec[best]):
                best = k
        if vec[best] < 0:
            vec = [-x for x in vec]
        comps.append(vec)
        ratios.append(vals[idx] / total)
    scores = []
    for c in centered:
        scores.append([math.fsum(c[k] * vec[k] for k in range(m)) for vec in comps])
    return scores, ratios

