    except TypeError:
        raise ValueError("data must be a list of rows")
    if len(rows) == 0:
        raise ValueError("data must not be empty")
    p = len(rows[0])
    if any(len(r) != p for r in rows):
        raise ValueError("rows have different lengths")
    n = len(rows)
    if isinstance(n_components, bool):
        raise ValueError("n_components must be an integer")
    try:
        if int(n_components) != n_components:
            raise ValueError("n_components must be an integer")
    except (TypeError, OverflowError):
        raise ValueError("n_components must be an integer")
    k = int(n_components)
    max_k = min(n - 1, p)
    if k < 1 or k > max_k:
        raise ValueError("n_components out of range")
    try:
        X = np.array(rows, dtype=float)
    except (TypeError, ValueError):
        raise ValueError("data must be numeric")
    if not np.all(np.isfinite(X)):
        raise ValueError("data must be finite")
    if np.all(X == X[0]):
        raise ValueError("data has zero total variance")
    Xc = X - X.mean(axis=0)
    U, S, Vt = np.linalg.svd(Xc, full_matrices=False)
    var = S ** 2
    total = var.sum()
    if total <= 0 or not np.isfinite(total):
        raise ValueError("data has zero total variance")
    order = np.argsort(-var, kind="stable")
    var = var[order]
    Vt = Vt[order]
    V = Vt[:k].T.copy()
    for j in range(k):
        idx = int(np.argmax(np.abs(V[:, j])))
        if V[idx, j] < 0:
            V[:, j] = -V[:, j]
    scores = Xc @ V
    ratios = var[:k] / total
    return ([[float(x) for x in row] for row in scores], [float(r) for r in ratios])

