        blk = bytes(a ^ b for a, b in zip(data[i:i + 16], prev))
        prev = _encrypt_block(blk, round_keys)
        out += prev
    return bytes(out)


def fernet_token(key, plaintext, iv, timestamp):
    if isinstance(key, str):
        try:
            key_b = key.encode('ascii')
        except UnicodeEncodeError:
