import math


def _jacobi_eig(A, max_sweeps=100):
    n = len(A)
    a = [row[:] for row in A]
    v = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for _ in range(max_sweeps):
        off = sum(a[i][j] ** 2 for i in range(n) for j in range(n) if i != j)
        if off < 1e-30:
            break
        for p in range(n - 1):
            for q in range(p + 1, n):
                if abs(a[p][q]) < 1e-300:
                    continue
                theta = (a[q][q] - a[p][p]) / (2.0 * a[p][q])
                t = (1.0 if theta >= 0 else -1.0) / (abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp = a[k][p]
                    akq = a[k][q]
                    a[k][p] = c * akp - s * akq
                    a[k][q] = s * akp + c * akq
                for k in range(n):
                    apk = a[p][k]
                    aqk = a[q][k]
                    a[p][k] = c * apk - s * aqk
                    a[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp = v[k][p]
                    vkq = v[k][q]
                    v[k][p] = c * vkp - s * vkq
                    v[k][q] = s * vkp + c * vkq
    return [a[i][i] for i in range(n)], v


def _pinv_solve(A, b):
    n = len(A)
    vals, vecs = _jacobi_eig(A)
    maxv = max([abs(x) for x in vals] + [0.0])
    tol = maxv * n * 1e-12
    w = [0.0] * n
    for k in range(n):
        lam = vals[k]
        if abs(lam) <= tol or lam == 0.0:
            continue
        proj = sum(vecs[i][k] * b[i] for i in range(n)) / lam
        for i in range(n):
            w[i] += proj * vecs[i][k]
    return w


def _solve(A, b):
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]
    scale = max([abs(A[i][i]) for i in range(n)] + [0.0])
    tol = scale * 1e-12 if scale > 0 else 1e-300
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) <= tol:
            return _pinv_solve(A, b)
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for r in range(col + 1, n):
            f = M[r][col] / pv
            if f != 0.0:
                for c in range(col, n + 1):
                    M[r][c] -= f * M[col][c]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n] - sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def _fit(X, y, alpha):
    m = len(X)
    p = len(X[0])
    xm = [sum(row[j] for row in X) / m for j in range(p)]
    ym = sum(y) / m
    Xc = [[row[j] - xm[j] for j in range(p)] for row in X]
    yc = [t - ym for t in y]
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p
    for r in range(m):
        row = Xc[r]
        for i in range(p):
            ri = row[i]
            b[i] += ri * yc[r]
            for j in range(p):
                A[i][j] += ri * row[j]
    for i in range(p):
        A[i][i] += alpha
    w = _solve(A, b)
    intercept = ym - sum(xm[j] * w[j] for j in range(p))
    return intercept, w


def ridge_kfold_r2(features, targets, alpha, n_folds):
    if features is None or targets is None:
        raise ValueError("inputs must not be None")
    features = list(features)
    targets = list(targets)
    n = len(features)
    if n == 0 or len(targets) == 0:
        raise ValueError("empty input")
    if n != len(targets):
        raise ValueError("length mismatch")
    rows = []
    for row in features:
        try:
            r = [float(v) for v in row]
        except TypeError:
            raise ValueError("invalid row")
        rows.append(r)
    p = len(rows[0])
    if p == 0:
        raise ValueError("no features")
    for r in rows:
        if len(r) != p:
            raise ValueError("ragged rows")
    y = [float(t) for t in targets]
    if alpha < 0:
        raise ValueError("alpha must be non-negative")
    if isinstance(n_folds, bool) or n_folds != int(n_folds):
        raise ValueError("n_folds must be an integer")
    n_folds = int(n_folds)
    if n_folds < 2 or n_folds > n / 2.0:
        raise ValueError("invalid n_folds")
    base, extra = divmod(n, n_folds)
    bounds = []
    start = 0
    for k in range(n_folds):
        size = base + (1 if k < extra else 0)
        bounds.append((start, start + size))
        start += size
    for s, e in bounds:
        fy = y[s:e]
        if all(v == fy[0] for v in fy):
            raise ValueError("fold targets are constant")
    scores = []
    for s, e in bounds:
        trX = rows[:s] + rows[e:]
        trY = y[:s] + y[e:]
        intercept, w = _fit(trX, trY, float(alpha))
        teX = rows[s:e]
        teY = y[s:e]
        preds = [intercept + sum(w[j] * r[j] for j in range(p)) for r in teX]
        mean_t = sum(teY) / len(teY)
        ss_tot = sum((t - mean_t) ** 2 for t in teY)
        ss_res = sum((t - q) ** 2 for t, q in zip(teY, preds))
        if ss_tot == 0:
            raise ValueError("fold targets are constant")
        scores.append(1.0 - ss_res / ss_tot)
    return sum(scores) / len(scores), scores

