import numpy as np


def _fit_ridge(X, y, alpha):
    x_mean = X.mean(axis=0)
    y_mean = y.mean()
    Xc = X - x_mean
    yc = y - y_mean
    p = X.shape[1]
    A = Xc.T @ Xc + alpha * np.eye(p)
    b = Xc.T @ yc
    try:
        if alpha > 0:
            w = np.linalg.solve(A, b)
        else:
            raise np.linalg.LinAlgError
    except np.linalg.LinAlgError:
        w = np.linalg.lstsq(A, b, rcond=None)[0]
    intercept = y_mean - x_mean @ w
    return intercept, w


def ridge_kfold_r2(features, targets, alpha, n_folds):
    if features is None or targets is None:
        raise ValueError("inputs must not be None")
    features = list(features)
    targets = list(targets)
    n = len(features)
    if n == 0 or len(targets) == 0:
        raise ValueError("inputs must not be empty")
    if n != len(targets):
        raise ValueError("features and targets differ in length")
    try:
        rows = [list(r) for r in features]
    except TypeError:
        raise ValueError("each feature row must be a sequence")
    p = len(rows[0])
    if p == 0:
        raise ValueError("rows must have at least one feature")
    for r in rows:
        if len(r) != p:
            raise ValueError("ragged feature rows")
    try:
        X = np.array(rows, dtype=float)
        y = np.array(targets, dtype=float)
        alpha = float(alpha)
    except (TypeError, ValueError):
        raise ValueError("non-numeric input")
    if y.ndim != 1:
        raise ValueError("targets must be one number per row")
    if not np.isfinite(alpha) or alpha < 0:
        raise ValueError("alpha must be non-negative")
    if isinstance(n_folds, bool):
        raise ValueError("n_folds must be an integer")
    try:
        if int(n_folds) != n_folds:
            raise ValueError("n_folds must be an integer")
    except TypeError:
        raise ValueError("n_folds must be an integer")
    k = int(n_folds)
    if k < 2 or 2 * k > n:
        raise ValueError("invalid n_folds")

    base, extra = divmod(n, k)
    bounds = []
    start = 0
    for i in range(k):
        size = base + (1 if i < extra else 0)
        bounds.append((start, start + size))
        start += size

    for s, e in bounds:
        yt = y[s:e]
        if np.all(yt == yt[0]):
            raise ValueError("a fold has constant targets")

    scores = []
    for s, e in bounds:
        mask = np.ones(n, dtype=bool)
        mask[s:e] = False
        intercept, w = _fit_ridge(X[mask], y[mask], alpha)
        Xt = X[s:e]
        yt = y[s:e]
        pred = intercept + Xt @ w
        ss_res = float(np.sum((yt - pred) ** 2))
        ss_tot = float(np.sum((yt - yt.mean()) ** 2))
        if ss_tot == 0:
            raise ValueError("a fold has constant targets")
        scores.append(1.0 - ss_res / ss_tot)

    mean_score = sum(scores) / len(scores)
    return (float(mean_score), [float(v) for v in scores])

