            return None
        n = int(parts[2])
        target = _DAYS[parts[3]]
        def f(y, m):
            wd = D(y, m, 1).weekday()
            day = 1 + (target - wd) % 7 + 7 * (n - 1)
            return [D(y, m, day)]
