import calendar
import re
from datetime import date, timedelta

_DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']


def _last_day(y, m):
    return date(y, m, calendar.monthrange(y, m)[1])


def _monthly_func(freq):
    def first_b(y, m):
        d = date(y, m, 1)
        while d.weekday() >= 5:
            d += timedelta(days=1)
        return [d]

    def last_b(y, m):
        d = _last_day(y, m)
        while d.weekday() >= 5:
            d -= timedelta(days=1)
        return [d]

    table = {
        'month-start': lambda y, m: [date(y, m, 1)],
        'month-end': lambda y, m: [_last_day(y, m)],
        'bmonth-start': first_b,
        'bmonth-end': last_b,
        'semimonth-start': lambda y, m: [date(y, m, 1), date(y, m, 15)],
        'semimonth-end': lambda y, m: [date(y, m, 15), _last_day(y, m)],
        'quarter-start': lambda y, m: [date(y, m, 1)] if m in (1, 4, 7, 10) else [],
        'quarter-end': lambda y, m: [_last_day(y, m)] if m in (3, 6, 9, 12) else [],
        'year-start': lambda y, m: [date(y, 1, 1)] if m == 1 else [],
        'year-end': lambda y, m: [date(y, 12, 31)] if m == 12 else [],
    }
    if freq in table:
        return table[freq]
    mt = re.fullmatch(r'nth-weekday-([1-4])-(mon|tue|wed|thu|fri|sat|sun)', freq)
    if mt:
        n = int(mt.group(1))
        wd = _DAYS.index(mt.group(2))

        def nth(y, m):
            first = date(y, m, 1)
            off = (wd - first.weekday()) % 7
            return [date(y, m, 1 + off + 7 * (n - 1))]
        return nth
    return None


def _gen_dates(start, freq, count):
    out = []
    if freq == 'daily':
        return [start + timedelta(days=k) for k in range(count)]
    if freq == 'business':
        d = start
        while len(out) < count:
            if d.weekday() < 5:
                out.append(d)
            d += timedelta(days=1)
        return out
    if freq.startswith('weekly-') and freq[7:] in _DAYS:
        wd = _DAYS.index(freq[7:])
        d = start + timedelta(days=(wd - start.weekday()) % 7)
        return [d + timedelta(days=7 * k) for k in range(count)]
    func = _monthly_func(freq)
    if func is None:
        raise ValueError('Unsupported frequency: %r' % (freq,))
    y, m = start.year, start.month
    while len(out) < count:
        for d in func(y, m):
            if d >= start and len(out) < count:
                out.append(d)
        m += 1
        if m > 12:
            m = 1
            y += 1
    return out


def _valid_freq(freq):
    if not isinstance(freq, str):
        return False
    if freq in ('daily', 'business'):
        return True
    if freq.startswith('weekly-') and freq[7:] in _DAYS:
        return True
    return _monthly_func(freq) is not None


def price_schedule(start_date, prices, freq):
    if not _valid_freq(freq):
        raise ValueError('Unsupported frequency: %r' % (freq,))
    start = date.fromisoformat(start_date)
    prices = list(prices)
    if not prices:
        return []
    dates = _gen_dates(start, freq, len(prices))
    return [(d.isoformat(), float(p)) for d, p in zip(dates, prices)]
